import java.io.*;
import java.util.*;

public class VariantTwo {
    public static void main(String[] args) throws Exception {
        new VariantTwo().calculate();
    }

    public void calculate() throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter out = new PrintWriter(System.out);
        String[] input = br.readLine().split(" ");
        int n = Integer.parseInt(input[0]);
        long k = Long.parseLong(input[1]);
        final long MOD = 998244353;

        if (k >= n) {
            out.println(0);
            out.flush();
            return;
        }

        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];
        fact[0] = 1;
        invFact[0] = 1;

        for (int i = 1; i <= n; i++) {
            fact[i] = (fact[i - 1] * i) % MOD;
            invFact[i] = powMod(fact[i], MOD - 2, MOD);
        }

        int r = (int) (n - k);
        long sum = 0;

        for (int i = 1; i <= r; i++) {
            long term = fact[r] * invFact[r - i] % MOD;
            term = term * invFact[i] % MOD;
            term = term * powMod(i, n, MOD) % MOD;
            if ((r - i) % 2 == 1) {
                term = -term;
            }
            sum = (sum + term + MOD) % MOD;
        }

        long answer;
        if (k == 0) {
            answer = sum * fact[n] % MOD;
            answer = answer * invFact[r] % MOD;
            answer = answer * invFact[n - r] % MOD;
        } else {
            answer = 2 * sum % MOD;
            answer = answer * fact[n] % MOD;
            answer = answer * invFact[r] % MOD;
            answer = answer * invFact[n - r] % MOD;
        }
        out.println(answer);
        out.flush();
    }

    private long powMod(long base, long exp, long mod) {
        long result = 1;
        long cur = base % mod;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (result * cur) % mod;
            }
            cur = (cur * cur) % mod;
            exp >>= 1;
        }
        return result;
    }
}
