#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    string line;
    getline(cin, line);
    stringstream ss(line);
    int n;
    long long k;
    ss >> n >> k;
    const long long MOD = 998244353;

    if (k >= n) {
        cout << 0 << "\n";
        return 0;
    }

    vector<long long> fact(n + 1, 1);
    vector<long long> invFact(n + 1, 1);

    auto powMod = [&](long long base, long long exp, long long mod) {
        long long result = 1;
        long long cur = base % mod;
        while (exp > 0) {
            if (exp & 1) result = (result * cur) % mod;
            cur = (cur * cur) % mod;
            exp >>= 1;
        }
        return result;
    };

    for (int i = 1; i <= n; i++) {
        fact[i] = (fact[i - 1] * i) % MOD;
        invFact[i] = powMod(fact[i], MOD - 2, MOD);
    }

    int r = n - (int)k;
    long long sum = 0;

    for (int i = 1; i <= r; i++) {
        long long term = fact[r] * invFact[r - i] % MOD;
        term = term * invFact[i] % MOD;
        term = term * powMod(i, n, MOD) % MOD;
        if ((r - i) % 2 == 1) {
            term = -term;
        }
        sum = (sum + term + MOD) % MOD;
    }

    long long answer;
    if (k == 0) {
        answer = sum * fact[n] % MOD;
        answer = answer * invFact[r] % MOD;
        answer = answer * invFact[n - r] % MOD;
    } else {
        answer = 2 * sum % MOD;
        answer = answer * fact[n] % MOD;
        answer = answer * invFact[r] % MOD;
        answer = answer * invFact[n - r] % MOD;
    }

    cout << answer << "\n";

    return 0;
}
